import sys
import numpy as np
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    M = int(data[1])

    edges = [[] for _ in range(N+1)]
    for i in range(M):
        s = int(data[2 + 2*i])
        t = int(data[2 + 2*i + 1])
        edges[s].append(t)

    # Compute expected values for all nodes
    # E[i] is the expected number of steps from node i to node N
    E = [0.0] * (N + 1)
    E[N] = 0.0

    # Reverse graph for topological sort
    rev_edges = [[] for _ in range(N+1)]
    for s in range(1, N+1):
        for t in edges[s]:
            rev_edges[t].append(s)

    # Topological sort
    in_degree = [0] * (N+1)
    for t in range(1, N+1):
        for s in rev_edges[t]:
            in_degree[s] += 1

    queue = []
    for i in range(1, N+1):
        if in_degree[i] == 0:
            queue.append(i)

    topo_order = []
    while queue:
        u = queue.pop(0)
        topo_order.append(u)
        for v in edges[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Process nodes in topological order
    for u in topo_order:
        if u == N:
            continue
        k = len(edges[u])
        if k == 0:
            continue
        total = 0.0
        for v in edges[u]:
            total += E[v]
        E[u] = 1.0 + total / k

    # Now, find the best edge to block
    # For each edge, simulate blocking and compute new E[1]
    min_E = E[1]

    for s in range(1, N+1):
        for t in edges[s]:
            # Try blocking this edge
            new_edges = [edges[i].copy() for i in range(N+1)]
            new_edges[s].remove(t)
            if len(new_edges[s]) == 0:
                continue
            # Rebuild the expected values
            E_new = [0.0] * (N+1)
            E_new[N] = 0.0
            # Rebuild the graph
            rev_edges_new = [[] for _ in range(N+1)]
            for i in range(1, N+1):
                for j in new_edges[i]:
                    rev_edges_new[j].append(i)
            # Rebuild topological order
            in_degree_new = [0] * (N+1)
            for j in range(1, N+1):
                for i in rev_edges_new[j]:
                    in_degree_new[i] += 1
            queue_new = []
            for i in range(1, N+1):
                if in_degree_new[i] == 0:
                    queue_new.append(i)
            topo_order_new = []
            while queue_new:
                u = queue_new.pop(0)
                topo_order_new.append(u)
                for v in new_edges[u]:
                    in_degree_new[v] -= 1
                    if in_degree_new[v] == 0:
                        queue_new.append(v)
            # Compute new E
            for u in topo_order_new:
                if u == N:
                    continue
                k = len(new_edges[u])
                if k == 0:
                    continue
                total = 0.0
                for v in new_edges[u]:
                    total += E_new[v]
                E_new[u] = 1.0 + total / k
            # Update min_E
            if E_new[1] < min_E:
                min_E = E_new[1]

    print("{0:.10f}".format(min_E))

if __name__ == "__main__":
    main()
